//! Première phrase des commentaires de documentation (REQ-243, DEC-180).

use tree_sitter::Node;

const MIN_WORDS: usize = 5;
const MAX_CHARS: usize = 300;
const TRIVIAL_STARTS: [&str; 5] = [
    "todo",
    "fixme",
    "created by",
    "generated by",
    "auto-generated",
];

/// Première phrase d'un commentaire `/** … */`, si elle est assez informative.
pub(crate) fn first_sentence(comment: &str) -> Option<String> {
    let body = comment.strip_prefix("/**")?;
    let body = body.strip_suffix("*/").unwrap_or(body);
    // (1) et (2) : lignes nettoyées, arrêt à la première ligne vide ou à une balise `@`.
    let mut kept: Vec<&str> = Vec::new();
    for line in body.lines() {
        let line = line.trim_start();
        let line = match line.strip_prefix('*') {
            Some(rest) => rest.strip_prefix(' ').unwrap_or(rest),
            None => line,
        };
        let line = line.trim();
        if line.is_empty() {
            if kept.is_empty() {
                continue;
            }
            break;
        }
        if line.starts_with('@') {
            break;
        }
        kept.push(line);
    }
    let text = kept.join("\n");
    let text = strip_html(&strip_links(&inline_tags(&text)));
    let text = text
        .replace("&lt;", "<")
        .replace("&gt;", ">")
        .replace("&quot;", "\"")
        .replace("&nbsp;", " ")
        .replace("&amp;", "&");
    let text = text.split_whitespace().collect::<Vec<_>>().join(" ");
    let sentence = cut_sentence(&text);
    let words = sentence.split_whitespace().count();
    let lower = sentence.to_lowercase();
    let trivial = TRIVIAL_STARTS.iter().any(|t| lower.starts_with(t));
    (words >= MIN_WORDS && sentence.chars().count() <= MAX_CHARS && !trivial)
        .then(|| sentence.to_string())
}

/// `{@link A}` → `A`, `{@link A texte}` → `texte`, `{@nom x}` → `x`.
fn inline_tags(text: &str) -> String {
    let mut out = String::new();
    let mut rest = text;
    while let Some(start) = rest.find("{@") {
        let Some(len) = rest[start..].find('}') else {
            break;
        };
        out.push_str(&rest[..start]);
        let inner = &rest[start + 2..start + len];
        let (name, arg) = match inner.split_once(char::is_whitespace) {
            Some((n, a)) => (n, a.trim()),
            None => (inner, ""),
        };
        if matches!(name, "link" | "linkplain") {
            match arg.split_once(char::is_whitespace) {
                Some((_, label)) => out.push_str(label.trim()),
                None => out.push_str(arg),
            }
        } else {
            out.push_str(arg);
        }
        rest = &rest[start + len + 1..];
    }
    out.push_str(rest);
    out
}

/// `[texte](cible)` → `texte`, `[A]` → `A`.
fn strip_links(text: &str) -> String {
    let mut out = String::new();
    let mut rest = text;
    while let Some(start) = rest.find('[') {
        let Some(end) = rest[start..].find(']') else {
            break;
        };
        out.push_str(&rest[..start]);
        out.push_str(&rest[start + 1..start + end]);
        rest = &rest[start + end + 1..];
        if rest.starts_with('(') {
            if let Some(close) = rest.find(')') {
                rest = &rest[close + 1..];
            }
        }
    }
    out.push_str(rest);
    out
}

/// Retire les balises HTML `<…>` (un `<` suivi d'une lettre, de `/` ou de `!`).
fn strip_html(text: &str) -> String {
    let mut out = String::new();
    let mut rest = text;
    while let Some(start) = rest.find('<') {
        let tag = rest[start + 1..].chars().next();
        let end = rest[start..].find('>');
        match (tag, end) {
            (Some(c), Some(e)) if c.is_alphabetic() || c == '/' || c == '!' => {
                out.push_str(&rest[..start]);
                rest = &rest[start + e + 1..];
            }
            _ => {
                out.push_str(&rest[..start + 1]);
                rest = &rest[start + 1..];
            }
        }
    }
    out.push_str(rest);
    out
}

/// Coupe après le premier `.`, `!` ou `?` suivi d'un blanc ou de la fin.
fn cut_sentence(text: &str) -> &str {
    let mut chars = text.char_indices().peekable();
    while let Some((i, c)) = chars.next() {
        if matches!(c, '.' | '!' | '?') && chars.peek().is_none_or(|(_, n)| n.is_whitespace()) {
            return &text[..i + c.len_utf8()];
        }
    }
    text
}

/// Doc du nœud `node` : commentaire `/**` qui le précède juste avant (ou qui précède l'`export`
/// qui l'englobe), rendu par `first_sentence`.
pub(crate) fn doc_before(node: Node, src: &[u8]) -> Option<String> {
    let (prev, start) = match node.prev_named_sibling() {
        Some(p) => (p, node.start_byte()),
        None => {
            let parent = node.parent().filter(|p| p.kind() == "export_statement")?;
            (parent.prev_named_sibling()?, parent.start_byte())
        }
    };
    if !prev.kind().contains("comment") {
        return None;
    }
    let text = std::str::from_utf8(src.get(prev.byte_range())?).ok()?;
    if !text.starts_with("/**") || text == "/**/" {
        return None;
    }
    let between = src.get(prev.end_byte()..start)?;
    between
        .iter()
        .all(u8::is_ascii_whitespace)
        .then(|| first_sentence(text))
        .flatten()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn req243_ac1_premiere_phrase() {
        let c = "/**\n * Calcule le montant de l'amende due. Les jours fériés comptent.\n * @param jours nombre de jours\n */";
        assert_eq!(
            first_sentence(c).as_deref(),
            Some("Calcule le montant de l'amende due.")
        );
    }

    #[test]
    fn req243_ac2_balises_et_entites() {
        let f = |c: &str| first_sentence(c).unwrap();
        assert_eq!(
            f("/** Renvoie le {@code Livre} lié à {@link Emprunt#livre l'emprunt} donné, ou <b>null</b>. */"),
            "Renvoie le Livre lié à l'emprunt donné, ou null."
        );
        assert_eq!(
            f("/** Trie la liste &lt;T&gt; selon l'ordre naturel donné. */"),
            "Trie la liste <T> selon l'ordre naturel donné."
        );
        assert_eq!(
            f("/** Envoie un rappel à [Adherent] pour chaque [prêt en retard](Emprunt). */"),
            "Envoie un rappel à Adherent pour chaque prêt en retard."
        );
        assert_eq!(
            f("/** Renvoie {@link Emprunt} pour le livre donné ici. */"),
            "Renvoie Emprunt pour le livre donné ici."
        );
    }

    #[test]
    fn req243_ac3_lignes_et_numeros() {
        let c = "/**\n * Service de calcul des amendes\n * pour les prêts en retard\n *\n * Détails.\n */";
        assert_eq!(
            first_sentence(c).as_deref(),
            Some("Service de calcul des amendes pour les prêts en retard")
        );
        let v = "/** Version 1.2 du format d'échange des notices. */";
        assert_eq!(
            first_sentence(v).as_deref(),
            Some("Version 1.2 du format d'échange des notices.")
        );
    }

    #[test]
    fn req243_ac4_pas_de_doc() {
        for c in [
            "/** Getter for x. */",
            "/** {@inheritDoc} */",
            "/** @return le titre */",
            "/** Created by jdupont on 12/03/2019. */",
            "/** todo : décrire cette classe un jour. */",
            "/**/",
        ] {
            assert_eq!(first_sentence(c), None, "{c}");
        }
        let long = format!("/** a b c d {} */", "b".repeat(293));
        assert_eq!(first_sentence(&long), None);
        let ok = format!("/** a b c d {} */", "é".repeat(292));
        assert_eq!(first_sentence(&ok).unwrap().chars().count(), 300);
        let ko = format!("/** a b c d {} */", "é".repeat(293));
        assert_eq!(first_sentence(&ko), None);
    }
}
